   case 'sites':self::required($d,['name','technology']);if(mb_strlen($d['name'])>120||!in_array($d['technology'],['Wind','Solar','BESS']))throw new HSE_Fault('Nome o tecnologia non validi');break;
   case 'areas':self::required($d,['name','type']);break;
   case 'companies':self::required($d,['name']);break;
   case 'memberships':self::required($d,['user_id','role']);if(!get_userdata((int)$d['user_id'])||!in_array($d['role'],['manager','reader','company']))throw new HSE_Fault('Utente o ruolo non valido');if($d['role']==='company')self::required($d,['company_id']);foreach(HSE_Store::list('memberships',$d['site_id']) as $m)if((int)$m['user_id']===(int)$d['user_id']&&(!$old||$old['id']!==$m['id']))throw new HSE_Fault('Assegnazione già presente',409);break;
   case 'observations':self::number($d,'longitude',-180,180);self::number($d,'latitude',-90,90);if(empty($d['note'])&&empty($d['attachments']))throw new HSE_Fault('Inserisci una nota o una foto');$d['status']=$d['status']??'Draft';if(!in_array($d['status'],['Draft','Registered']))throw new HSE_Fault('Stato non valido');$d['observed_at']=$d['observed_at']??gmdate('c');break;
   case 'assessments':
