    if(isset($d['formal_events'])||isset($d['informal_events']))$d['events']=array_merge(array_map(fn($e)=>array_merge($e,['channel'=>'formal']),$d['formal_events']??[]),array_map(fn($e)=>array_merge($e,['channel'=>'informal']),$d['informal_events']??[]));$d['event_snapshots']=[];$eventIds=[];foreach($d['event_ids']??[] as $id){if(in_array($id,$eventIds))throw new HSE_Fault('Segnalazione selezionata due volte');$eventIds[]=$id;$e=self::reference($id,'events',$d['site_id']);HSE_Store::permit($d['site_id'],false,'events',$e);if(!HSE_Period::event_in_period($e,$d))throw new HSE_Fault('Segnalazione fuori periodo o chiusura già considerata');$d['event_snapshots'][]=$e;}
    $refs=[];$seenEventIds=[];foreach(array_merge($d['events']??[],$d['event_snapshots']) as $e){if(!empty($e['id'])){if(in_array($e['id'],$seenEventIds))throw new HSE_Fault('Stessa segnalazione inserita più volte');$seenEventIds[]=$e['id'];}self::event($e);if(!empty($e['reference'])){if(in_array($e['reference'],$refs))throw new HSE_Fault('Riferimento evento duplicato nei canali');$refs[]=$e['reference'];}}
    $sessionIds=[];foreach($d['sensitizations']??[] as $s){if(!empty($s['session_id'])){if(in_array($s['session_id'],$sessionIds))throw new HSE_Fault('Incontro già riutilizzato');$sessionIds[]=$s['session_id'];$session=self::reference($s['session_id'],'sessions',$d['site_id']);if(mb_strtolower($session['topic'])!==mb_strtolower($s['topic'])||$session['count']!=$s['count']||($session['coverage']??null)!==($s['coverage']??null))throw new HSE_Fault('Dati incontro differenti dalla fonte: aggiornare o scollegare');if(!HSE_Period::session_in_period($session,$d))throw new HSE_Fault('Incontro fuori periodo');}self::required($s,['topic','count']);self::number($s,'count',1,10000,true);self::number($s,'coverage',0,100);}
    $d['status']='Draft';$d['model_version']='2.0.0';unset($d['result'],$d['calculated_at'],$d['calculated_input_hash'],$d['model_input']);break;
   case 'checklists':self::required($d,['title','items']);foreach($d['items'] as $item){self::required($item,['text','state']);if(!in_array($item['state'],['Da verificare','Verificato','Non applicabile']))throw new HSE_Fault('Stato verifica non valido');}break;
   case 'events':if(!empty($d['event_date'])){if(!self::date($d['event_date'])||$d['event_date']>self::today('Y-m-d'))throw new HSE_Fault('Data segnalazione non valida');$d['month']=substr($d['event_date'],0,7);}if(!$old&&!empty($d['observation_id']))foreach(HSE_Store::list('events',$d['site_id']) as $event)if(($event['observation_id']??'')===$d['observation_id'])throw new HSE_Fault('Segnalazione già collegata al sopralluogo',409,['id'=>$event['id']]);self::event($d);$d['status']=$d['status']??'Draft';break;
   case 'plans':
    self::required($d,['company_id','week']);if(!$old&&!empty($d['import_hash']))foreach(HSE_Store::list('plans',$d['site_id']) as $existing)if(($existing['import_hash']??'')===$d['import_hash']&&$existing['company_id']===$d['company_id']&&$existing['week']===$d['week'])throw new HSE_Fault('Import già presente: riapri e revisiona il sinottico esistente',409,['id'=>$existing['id']]);if(!self::date($d['week'])||date('N',strtotime($d['week']))!=='1')throw new HSE_Fault('La settimana deve iniziare di lunedì');
    $d['status']='Draft';unset($d['published_at']);
    $d['activities']=$d['activities']??[];foreach($d['activities'] as &$a){$a['id']=$a['id']??wp_generate_uuid4();if(!empty($a['area_id']))self::reference($a['area_id'],'areas',$d['site_id']);foreach($a['days']??[] as $day){if(!self::date($day['date']??''))throw new HSE_Fault('Data attività non valida');self::number($day,'operators',0,100000,true);}}
