    if($old&&($old['status']??'')==='Finalized'){self::required($d,['revision_reason']);$d['status']='Preparation';}
    else $d['status']=$old['status']??'Preparation';
    if($old&&isset($old['source_snapshot']))$d['source_snapshot']=$old['source_snapshot'];
    foreach($d['items']??[] as $i){if(!empty($i['source_id']))self::reference($i['source_id'],$i['source_type']??'',$d['site_id']);if(!empty($i['action']))self::required($i,['owner','due_date']);}
    break;
   case 'actions':self::required($d,['description','owner','due_date']);if(!self::date($d['due_date']))throw new HSE_Fault('Scadenza non valida');if(!in_array($d['status']??'Open',['Open','In progress','Closed']))throw new HSE_Fault('Stato azione non valido');if(($d['status']??'')==='Closed')self::required($d,['evidence']);if(!empty($d['source_id']))self::reference($d['source_id'],$d['source_type']??'',$d['site_id']);break;
   case 'toolboxes':self::required($d,['title','content']);$d['status']='Prepared';break;
   case 'sessions':self::required($d,['toolbox_id','held_on','topic','count']);if(!self::date($d['held_on'])||$d['held_on']>self::today('Y-m-d'))throw new HSE_Fault('Data incontro non valida');self::number($d,'count',1,100000,true);self::number($d,'coverage',0,100);self::number($d,'recipients',0,100000,true);break;
   case 'documents':self::required($d,['title','category','declared_revision','document_date']);if(!self::date($d['document_date']))throw new HSE_Fault('Data documento non valida');if(empty($d['url'])&&empty($d['attachments']))throw new HSE_Fault('Inserire URL o allegato');if(!empty($d['url'])&&!preg_match('~^https://[^\s]+$~',$d['url']))throw new HSE_Fault('URL HTTPS richiesto');$d['current_by']=get_current_user_id();break;
   case 'maps':
    $d['parent_revision']=$old['version']??null;self::required($d,['title','geojson']);HSE_Maps::validate($d['geojson']);HSE_Landscape::validate($d['landscape']??[]);if(!in_array($d['map_layout']??'light',['light','landscape']))throw new HSE_Fault('Layout mappa non valido');
