 }
 static function asset($id,$site,$company=''){global $wpdb;$a=$wpdb->get_row($wpdb->prepare('SELECT id,site_id,company_id FROM '.HSE_Store::table('assets').' WHERE id=%s',$id),ARRAY_A);if(!$a||$a['site_id']!==$site||($company&&$a['company_id']!==$company))throw new HSE_Fault('Allegato non valido');HSE_Store::permit($site,false,'assets',$a);return $a;}
 static function event($e){self::required($e,['topic','severity','state','channel']);if(!in_array($e['severity'],['Low','Medium','High'])||!in_array($e['state'],['Open','Closed on time','Closed late'])||!in_array($e['channel'],['formal','informal']))throw new HSE_Fault('Segnalazione non valida');if(!empty($e['overdue'])&&$e['state']!=='Open')throw new HSE_Fault('Ritardo applicabile solo ad eventi aperti');if($e['severity']==='High')self::required($e,['reason']);}
 static function confirm_plan($p){
  self::required($p,['activities','confirmed_review','daily_totals']);if($p['confirmed_review']!==true)throw new HSE_Fault('Conferma esplicita richiesta');$sums=[];$ids=[];
  foreach($p['activities'] as $a){self::required($a,['id','description','area_id','supervisor','pos','days','conditions_reviewed']);if(in_array($a['id'],$ids))throw new HSE_Fault('Attività duplicata');$ids[]=$a['id'];self::reference($a['area_id'],'areas',$p['site_id']);if(($a['conditions_reviewed']??false)!==true)throw new HSE_Fault('Condizioni operative da verificare');$dateSeen=[];foreach($a['days'] as $day){self::required($day,['date']);if(in_array($day['date'],$dateSeen))throw new HSE_Fault('Data duplicata nella stessa attività');$dateSeen[]=$day['date'];if(!isset($day['operators'])||$day['operators']==='')throw new HSE_Fault('Operatori da integrare');self::number($day,'operators',0,100000,true);if($day['date']<$p['week']||$day['date']>date('Y-m-d',strtotime($p['week'].' +6 days')))throw new HSE_Fault('Attività fuori settimana');$sums[$day['date']]=($sums[$day['date']]??0)+(int)$day['operators'];}}
  foreach($sums as $date=>$sum){$total=null;foreach($p['daily_totals'] as $t)if($t['date']===$date){self::number($t,'workers',0,100000,true);$total=$t['workers']??null;}if($total===null||$total==='')throw new HSE_Fault('Forza lavoro dichiarata mancante: '.$date);if((int)$total!==$sum&&empty($p['totals_reason']))throw new HSE_Fault('Discrepanza tra somma attività e forza lavoro: motivare senza duplicare persone');}
  foreach($p['activities'] as &$activity){foreach($activity['provenance']??[] as $key=>$prov){$value=$activity[$prov['field']]??null;if($prov['field']==='operators')foreach($activity['days'] as $day)if($day['date']===($prov['date']??''))$value=$day['operators'];$activity['provenance'][$key]['normalized']=$value;$activity['provenance'][$key]['manual_correction']=(string)$value!==(string)($prov['original']??'');$activity['provenance'][$key]['status']='Verificato dall’utente';}}unset($activity);$p['status']='Confirmed';$p['published_at']=gmdate('c');return $p;
 }
 static function calendar($site,$filters=[]){foreach(['from','to'] as $key)if(!empty($filters[$key])&&!self::date($filters[$key]))throw new HSE_Fault('Filtro data non valido');
  $plans=[];global $wpdb;foreach(HSE_Store::list('plans',$site) as $p){
   if($p['status']!=='Confirmed'){
    $revs=$wpdb->get_results($wpdb->prepare('SELECT version,payload FROM '.HSE_Store::table('revisions').' WHERE record_id=%s ORDER BY version DESC',$p['id']),ARRAY_A);
    foreach($revs as $rev){$data=json_decode($rev['payload'],true);if(($data['status']??'')==='Confirmed'){$p=array_merge($p,$data,['version'=>(int)$rev['version'],'updated_at'=>$data['published_at']]);break;}}
   }
   if($p['status']==='Confirmed'&&HSE_Store::access($site,false,'plans',$p))$plans[]=$p;
  }$latest=[];
  foreach($plans as $p){$key=$p['company_id'].'/'.$p['week'];if(!isset($latest[$key])||strcmp($p['updated_at'],$latest[$key]['updated_at'])>0)$latest[$key]=$p;}
  $companyNames=[];$areaNames=[];foreach(HSE_Store::list('companies',$site) as $co)$companyNames[$co['id']]=$co['name'];foreach(HSE_Store::list('areas',$site) as $ar)$areaNames[$ar['id']]=$ar['name'];$rows=[];foreach($latest as $p)foreach($p['activities'] as $a)foreach($a['days'] as $day){$r=array_merge($a,$day,['plan_id'=>$p['id'],'company_id'=>$p['company_id'],'company_name'=>$companyNames[$p['company_id']]??$p['company_id'],'area_name'=>$areaNames[$a['area_id']]??$a['area_id'],'revision'=>$p['version'],'published_at'=>$p['published_at'],'daily_totals'=>$p['daily_totals']]);if(!empty($filters['from'])&&$r['date']<$filters['from'])continue;if(!empty($filters['to'])&&$r['date']>$filters['to'])continue;$keep=true;foreach(['area_id','company_id'] as $k)if(!empty($filters[$k])&&$filters[$k]!==($r[$k]??''))$keep=false;if(!empty($filters['search'])&&stripos($r['description'].' '.$r['supervisor'],$filters['search'])===false)$keep=false;if(!empty($filters['condition'])&&in_array($filters['condition'],['night','hot_work','confined','closure'])&&empty($r[$filters['condition']]))$keep=false;if($keep)$rows[]=$r;}
  foreach($rows as &$r){$r['co_presence']=false;foreach($rows as $other)if($r['date']===$other['date']&&$r['area_id']===$other['area_id']&&$r['company_id']!==$other['company_id'])$r['co_presence']=true;}unset($r);
  usort($rows,fn($a,$b)=>strcmp($a['date'],$b['date']));return $rows;
 }
 static function prepare_meeting($site,$d){
  self::required($d,['week']);if(!self::date($d['week'])||date('N',strtotime($d['week']))!=='1')throw new HSE_Fault('Settimana riunione: scegliere lunedì');$rows=self::calendar($site,['from'=>$d['week'],'to'=>date('Y-m-d',strtotime($d['week'].' +6 days'))]);$items=[];$observations=[];
  foreach($rows as $r)$items[]=['id'=>wp_generate_uuid4(),'source_type'=>'plans','source_id'=>$r['plan_id'],'text'=>$r['date'].' · '.$r['description'].($r['co_presence']?' · Compresenza da verificare':''),'source_version'=>$r['revision'],'source_updated_at'=>$r['published_at'],'decision'=>'','action'=>''];
  foreach($d['observation_ids']??[] as $id){$o=self::reference($id,'observations',$site);HSE_Store::permit($site,false,'observations',$o);$observations[]=$o;$items[]=['id'=>wp_generate_uuid4(),'source_type'=>'observations','source_id'=>$id,'source_version'=>$o['version'],'source_updated_at'=>$o['updated_at'],'text'=>$o['note']??'Foto sopralluogo','decision'=>'','action'=>''];}
  return ['site_id'=>$site,'title'=>'Riunione di coordinamento','meeting_date'=>$d['week'],'week'=>$d['week'],'status'=>'Preparation','items'=>$items,'source_snapshot'=>['calendar'=>$rows,'observations'=>$observations,'observation_ids'=>$d['observation_ids']??[],'generated_at'=>gmdate('c')]];
 }
 static function toolbox($site,$d){
  $text=$d['activity']??'';$sources=[];foreach($d['source_refs']??[] as $ref){$plan=self::reference($ref['plan_id']??'','plans',$site);HSE_Store::permit($site,false,'plans',$plan);if($plan['status']!=='Confirmed')throw new HSE_Fault('Usare un sinottico confermato');$found=false;foreach($plan['activities'] as $a)if($a['id']===($ref['activity_id']??'')){$sources[]=['plan_id'=>$plan['id'],'activity_id'=>$a['id'],'revision'=>$plan['version'],'description'=>$a['description']];$text.=' · '.$a['description'];$found=true;}if(!$found)throw new HSE_Fault('Attività sorgente non trovata');}
  if(!$text)throw new HSE_Fault('Selezionare una attività o una lavorazione');$documentText=[];foreach($d['document_refs']??[] as $id){$doc=self::reference($id,'documents',$site);HSE_Store::permit($site,false,'documents',$doc);$documentText[]=$doc['title'].' · rev. '.$doc['declared_revision'];}$themes=[];
  $library=json_decode(file_get_contents(dirname(__DIR__,3).'/hse-risk-platform/includes/toolbox-catalog.json'),true);$matches=['elettr'=>'elettrico','scav'=>'scavi','quota'=>'quota','sollev'=>'sollevamento','confin'=>'spazi confinati','caldo'=>'incendio','hot work'=>'incendio','viabil'=>'viabilità','mezzi'=>'viabilità','dpi'=>'dpi','ordine'=>'ordine e pulizia','document'=>'documentale','ambient'=>'ambientale'];$used=[];
  foreach($matches as $key=>$theme)if(mb_stripos($text.' '.($d['conditions']??''),$key)!==false&&!in_array($theme,$used)){$used[]=$theme;$t=$library[$theme];$themes[]=($theme==='sollevamento'?'Sollevamenti':ucfirst($theme)).': '.$t[0]."\n".implode("\n",$t[1])."\nDiscussione: ".$t[2];}
  if(!$themes)$themes[]='Verificare rischi e misure nei documenti applicabili alla lavorazione.';
  return ['site_id'=>$site,'title'=>'Toolbox · '.$text,'template_id'=>'source-3.1.0-discussion','template_version'=>'3.1.0-doc3-2026-10-16','status'=>'Prepared','content'=>"Attività: $text\n".implode("\n",$themes)."\nCondizioni dichiarate: ".($d['conditions']??'Da integrare')."\nDocumenti: verificare revisione e misure; nessuna prescrizione estratta senza fonte.\nDomande: quali cambiamenti rispetto al piano? Chi contattare per chiarimenti?\nIn caso di condizioni non chiarite, interrompere e richiedere verifica al referente.\nSupporto alla discussione, non autorizzazione al lavoro.",'source_refs'=>$sources,'document_refs'=>$d['document_refs']??[],'document_references'=>$documentText];
 }
